function keyOf(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

export function expansionCardsFor(industrySlug: string): ExpansionCard[] {
  const glossaryCards = (GLOSSARIES[industrySlug] || []).map(([term, definition, vietnamExample, candidateUse], index) => ({
    key: `glossary-${String(index + 1).padStart(2, '0')}-${keyOf(term)}`,
    module: 0,
    topic: 'glossary' as TopicGroupId,
    emoji: '',
    type: 'concept' as const,
    title: term,
    front: definition,
    back: [`Vietnam example: ${vietnamExample}`, `Why it matters: ${candidateUse}`],
  }));

  const subsectorCards = SUBSECTORS.filter((profile) => profile.parent === industrySlug).flatMap((profile) => {
    const base = keyOf(profile.label);
    return [
      { key: `${base}-overview`, module: 6, topic: profile.topic, emoji: '', type: 'fact' as const, title: `${profile.label}: market overview`, front: profile.overview[0], back: profile.overview.slice(1) },
      { key: `${base}-players`, module: 6, topic: profile.topic, emoji: '', type: 'fact' as const, title: `${profile.label}: key players in Vietnam`, front: profile.players[0], back: profile.players.slice(1) },
      { key: `${base}-economics`, module: 7, topic: profile.topic, emoji: '', type: 'concept' as const, title: `${profile.label}: economics & unit structure`, front: profile.economics[0], back: profile.economics.slice(1) },
      { key: `${base}-careers`, module: 7, topic: profile.topic, emoji: '', type: 'role' as const, title: `${profile.label}: career paths`, front: profile.careers[0], back: profile.careers.slice(1) },
    ];
  });

  return [...glossaryCards, ...subsectorCards];
}
